<?php $editing=!empty($user);?><div class="dashboard-heading"><div><span class="eyebrow">USUÁRIOS</span><h2><?= $editing?'Editar usuário':'Criar usuário' ?></h2><p>O vínculo concede acesso operacional à loja, sem alterar seu vendedor proprietário.</p></div></div><form class="panel resource-form" method="post" action="<?= e($editing?url('/admin/usuarios/'.$user['id']):url('/admin/usuarios')) ?>"><?= csrf_field() ?><?php if($editing):?><input type="hidden" name="_method" value="PUT"><?php endif;?><div class="form-grid"><label>Nome<input name="name" required value="<?= e($user['name']??'') ?>"></label><label>E-mail<input type="email" name="email" required value="<?= e($user['email']??'') ?>"></label><label>Telefone<input name="phone" value="<?= e($user['phone']??'') ?>"></label><label>Senha <?= $editing?'<small>Deixe vazia para manter</small>':'' ?><input type="password" name="password" minlength="12" <?= $editing?'':'required' ?>><small>12 caracteres, com maiúscula, minúscula, número e símbolo.</small></label><label>Perfil<select name="type"><?php foreach(['operator'=>'Operador','seller'=>'Vendedor','customer'=>'Cliente','admin'=>'Administrador'] as $value=>$label):?><option value="<?= $value ?>" <?= ($user['type']??'operator')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active">Ativo</option><option value="inactive" <?= ($user['status']??'')==='inactive'?'selected':'' ?>>Inativo</option><option value="blocked" <?= ($user['status']??'')==='blocked'?'selected':'' ?>>Bloqueado</option></select></label><label>Vincular à loja<select name="store_id"><option value="">Sem vínculo</option><?php foreach($stores as $store):?><option value="<?= $store['id'] ?>" <?= (int)($link['store_id']??0)===(int)$store['id']?'selected':'' ?>><?= e($store['name']) ?></option><?php endforeach;?></select></label><label>Função na loja<select name="store_role"><?php foreach(['manager'=>'Gestor','catalog'=>'Catálogo','orders'=>'Pedidos','support'=>'Atendimento','finance'=>'Financeiro'] as $value=>$label):?><option value="<?= $value ?>" <?= ($link['role']??'manager')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label></div><div class="form-actions"><a class="button button--secondary" href="<?= e(url('/admin/usuarios')) ?>">Cancelar</a><button class="button button--primary">Salvar usuário</button></div></form>
